  VALUES 
    (816::BIGINT, 'Me parece extraño la calificación que el tiene aquí, si varias personas con las que he hablado y han llevado con el, están de acuerdo conmigo en las deficiencias del profe'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('45','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos']::TEXT[], '2026-07-24T00:00:00+00:00'::TIMESTAMPTZ, '3300159bbdf8ededde1dfbb4999547b3b1971c322970d23f50ab460bcc1cd55f'::TEXT, ARRAY[634]::BIGINT[]),
    (816::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('30','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2026-07-11T00:00:00+00:00'::TIMESTAMPTZ, '66fd3b66a0a04194f503a37d0c3440b8551d08aeb82f5d4abf9995a525897e47'::TEXT, ARRAY[634]::BIGINT[]),
    (816::BIGINT, 'El profe como persona es demasiado bueno, es muy duro como califica y no comprende de errores, aunque el en clases se equivoque muchisimo, es muy desordenado, tarda en calificar y llega tarde a dar la clase'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('45','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2026-07-03T00:00:00+00:00'::TIMESTAMPTZ, 'e2e61630e81f9ea4177290d2f889c1b88f00a230a930236a5979d2a5c7a0b509'::TEXT, ARRAY[634]::BIGINT[]),
    (816::BIGINT, 'Tarda mucho tiempo en entregar los exámenes, además, explica muy rápido y mal. Otra cosa es que siempre llega 20 minutos tarde a las clases'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-07-02T00:00:00+00:00'::TIMESTAMPTZ, '736c1da12dcef5c51c95037d76ed91a17ffee524f87935d91448d5cd9a3462e9'::TEXT, ARRAY[634]::BIGINT[]),
    (816::BIGINT, 'Muy buena persona y profesor. El curso se pasa fácil, pero se excede demasiado tiempo para entregar calificaciones.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Pocos exámenes', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2024-11-12T00:00:00+00:00'::TIMESTAMPTZ, '2b3f85560a2e227954092caf00446c3a72c0bf5a6d3778fdce173e85e6d8e5ee'::TEXT, ARRAY[968]::BIGINT[]),
    (816::BIGINT, 'Muy buen profe, explica muy claro. Además, genera mucha confianza, y como persona es muy agradable.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2023-10-14T00:00:00+00:00'::TIMESTAMPTZ, '2fea6ba2e47604fd83cf080f64a8b57c3d4bcb68928a2d318192fcbeba963aca'::TEXT, ARRAY[563]::BIGINT[]),
    (816::BIGINT, 'No pude haber llevado CDI con alguien mejor'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Clases excelentes']::TEXT[], '2023-10-03T00:00:00+00:00'::TIMESTAMPTZ, '41c29fe7ee2100529b528f8b7a6282784beaf626cc3217b9af1933807ea0fb3e'::TEXT, ARRAY[605]::BIGINT[]),
    (816::BIGINT, 'Hasta el momento ha sido el mejor profesor que he tenido, sus quices muy parecidos o más fáciles que lo visto en la clase, se le nota el dominio en el tema y se preocupa que el estudiante comprenda, explica las veces que sea necesario. Además, como persona es un 10/10.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-01-25T00:00:00+00:00'::TIMESTAMPTZ, 'ab370638d9cee843f97886bd42d4b75c563f0eff5ae861d9bb4ff717dca1b08e'::TEXT, ARRAY[563]::BIGINT[]),
    (816::BIGINT, 'Es super amable y se preocupa mucho por que la materia quede clara, explica las veces que sean necesarias hasta que uno entienda. Sabe mucho y tiene muy buen dominio. Super recomendado.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2022-12-15T00:00:00+00:00'::TIMESTAMPTZ, 'b0dd09e32b093a396e866cddd1aa12a36d62511aa4dc63638ad9ca5caee06f4b'::TEXT, ARRAY[563]::BIGINT[]),
    (816::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Clases largas']::TEXT[], '2022-02-25T00:00:00+00:00'::TIMESTAMPTZ, '3e61cb3137fca61e67e671df2ee5059537d2cac009e0206936ebdb42e7a4d00c'::TEXT, ARRAY[563]::BIGINT[]),
    (816::BIGINT, 'Es un excelente profesor, da gusto recibir clases con él, explica super bien y siempre esta dispuesto ayudar.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-12-06T00:00:00+00:00'::TIMESTAMPTZ, '4a42a3c167f1701f749fc42338f7feb2cf2d6591b3d961aac954b08b647ade81'::TEXT, ARRAY[563]::BIGINT[]),
    (816::BIGINT, 'En modalidad virtual deja pocos trabajos, en realidad son quices fáciles uno cada semana, adempas los 3 quices de cátedra y los 3 exámenes, así es su evaluación.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Brinda apoyo']::TEXT[], '2021-12-03T00:00:00+00:00'::TIMESTAMPTZ, '9f9bbe635de2f3d965e24ae2190160a65b8264f68fc447455a3c80d0cb36e933'::TEXT, ARRAY[563]::BIGINT[]),
    (816::BIGINT, 'Fue el mejor profesor que tuve este semestre, es super ordenado, brinda muchos materiales y es super claro en las explicaciones'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-12-01T00:00:00+00:00'::TIMESTAMPTZ, 'afa5433b7928747dfad23a93fe8b9e4e733ab21fc2e3bf33f438a281f1942507'::TEXT, ARRAY[563]::BIGINT[]),
    (816::BIGINT, 'El mejor profe de mate'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-07-14T00:00:00+00:00'::TIMESTAMPTZ, '2695c9ba6fcc5c773089996aaa29bfd31a6b9fb18eddf005a0d02d95691311dd'::TEXT, ARRAY[563]::BIGINT[]),
    (816::BIGINT, 'Es un excelente profesor, posee gran dominio del tema y se nota que dedica su tiempo para preparar el material de clase de los estudiantes, realiza explicaciones clara y excelente en hora consulta sin duda alguien con quien llevar el curso!'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-07-07T00:00:00+00:00'::TIMESTAMPTZ, 'fe395daa64aafb821d3a952a174e12b4bfac663e3f8cfb45b4869bfb12df225c'::TEXT, ARRAY[563]::BIGINT[]),
    (816::BIGINT, 'Es un gran profesor, da todos los materiales necesarios para poder aprender de buena manera y todo lo mantiene en gran orden. Debe ponerle a pasar ya que no regala nada y las clases son muy largas y cansan, pero la materia que imparte es la justa y necesaria.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases largas', 'Clases excelentes']::TEXT[], '2021-07-02T00:00:00+00:00'::TIMESTAMPTZ, '8178150beb45e64e8b2c64f1c630a0f1245c56d3a95a19626fc27aab0c2976ed'::TEXT, ARRAY[923]::BIGINT[]),
    (816::BIGINT, 'El profesor es sumamente ordenado y facilita muchos materiales que él mismo hace, se nota que se preocupa porque uno aprenda y en las horas de consulta se toma el tiempo que haga falta hasta que uno entienda. Definitivamente es el mejor profesor de matemática que he tenido.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-06-23T00:00:00+00:00'::TIMESTAMPTZ, '982abc27d311d0836412b46e1f7e6bf2e901acc818b30a549bc9fb3f70422e87'::TEXT, ARRAY[563, 923]::BIGINT[]),
    (816::BIGINT, 'Es un osito jajaja explica demasiado bien, muy amable en horas consulta, el mejor profe de mate de San Carlos. El Dios Guillén!!'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-03-24T00:00:00+00:00'::TIMESTAMPTZ, 'f46c7aa816d044918de2fab1ec90b4c860ddd3cc6e46abbd94f6a9803de121f0'::TEXT, ARRAY[634, 935]::BIGINT[]),
    (816::BIGINT, 'Excelente profe, explica las cosas muy claras y deja quices todas las semanas lo que ayuda a estar preparado(a) para los exámenes.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-02-06T00:00:00+00:00'::TIMESTAMPTZ, '4b05bb38deaaf61f545e142d148e358a15b2b802a5bff99902d87e5b964dfb5d'::TEXT, ARRAY[923]::BIGINT[]),
    (816::BIGINT, 'El profesor es excelente, con un perfecto dominio de lo que enseña y maneja muy bien la tecnología, se toma su tiempo para explicar muy bien las cosas, el mejor profesor de la escuela de matemática'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2021-02-02T00:00:00+00:00'::TIMESTAMPTZ, 'e272f36039183f89bed4d74cd778da07544535fadccf247eb3635fa89634ce96'::TEXT, ARRAY[923]::BIGINT[]),
    (816::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Inspirador']::TEXT[], '2020-10-23T00:00:00+00:00'::TIMESTAMPTZ, 'cdfdb1a22ed3ab05a04536dc79631ad550a74a7b815d0bde3b91894307ea7524'::TEXT, ARRAY[2439]::BIGINT[]),
    (816::BIGINT, 'Excelente profesor, explica de manera muy clara y le importa mucho el aprendizaje del estudiante, y su personalidad cómica evita que el estudiante se aburra en clase.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Brinda apoyo']::TEXT[], '2020-08-26T00:00:00+00:00'::TIMESTAMPTZ, 'bd07b8fbed3b4434d6aaeb42f2a68b295617c143e9c0bef96bea8e2f8ecf36f8'::TEXT, ARRAY[605]::BIGINT[]),
    (816::BIGINT, 'Es excelente profesor y persona. Explica muy a detalle. Sin embargo aplica demasiadas evaluaciones adicionales, no da tiempo a estudiar. Se excede en cuanto a presión en los grupos de WhatsApp/ notificaciones lo que hace que el curso sea vuelva tenso. Muy rutinario, las clases se tornan aburridas.'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Exámenes retadores']::TEXT[], '2020-08-21T00:00:00+00:00'::TIMESTAMPTZ, 'a6bd3c9e7f99f439017abfb587c0d8e802da3ccac0833581fc66b697b3c855a3'::TEXT, ARRAY[563]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
